// Builds rust/grid-core to WebAssembly and embeds it in the TypeScript source,
// so the npm package and the vanilla build need no Rust and no extra files.
//
//   rustup target add wasm32-unknown-unknown    (once)
//   npm run build:rust
//
// Writes src/grid/rust/gridCoreWasm.ts (generated, do not edit by hand).
// Commit that file: `npm run build` uses it and never needs Rust installed.
//
// No wasm32 target available (offline machine)? With the Rust library source
// installed, set YUKTAI_BUILD_STD=1 to build Rust's `core` from source instead.

import { execFileSync } from "node:child_process"
import { readFileSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))
const crate = join(here, "grid-core")
const target = "wasm32-unknown-unknown"

const args = ["build", "--release", "--target", target]
const env = { ...process.env }
if (process.env.YUKTAI_BUILD_STD === "1") {
  args.push("-Zbuild-std=core")
  env.RUSTC_BOOTSTRAP = "1"
}

execFileSync("cargo", args, { cwd: crate, env, stdio: "inherit" })

const wasmPath = join(crate, "target", target, "release", "yuktai_grid_core.wasm")
const bytes = readFileSync(wasmPath)

// Check it before embedding: right version, nothing imported.
const mod = new WebAssembly.Module(bytes)
if (WebAssembly.Module.imports(mod).length) throw new Error("grid-core must not import anything")
const inst = new WebAssembly.Instance(mod)
if (inst.exports.yk_version() !== 1) throw new Error("unexpected grid-core version")

const base64 = bytes.toString("base64")
const lines = base64.match(/.{1,100}/g).map((l) => `  "${l}"`).join(",\n")

const out = `// ─────────────────────────────────────────────────────────────────────────────
// GENERATED by rust/build-wasm.mjs from rust/grid-core. Do not edit by hand.
// Rebuild with: npm run build:rust
// ─────────────────────────────────────────────────────────────────────────────

/** yuktai grid-core WebAssembly (${bytes.length} bytes), base64. */
export const GRID_CORE_WASM_BASE64: string = [
${lines}
].join("")

export const GRID_CORE_WASM_SIZE = ${bytes.length}
`

const outPath = join(here, "..", "src", "grid", "rust", "gridCoreWasm.ts")
writeFileSync(outPath, out)
console.log(`grid-core: ${bytes.length} bytes → ${outPath}`)
